def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if path == "/":
            # Global cross-reference summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_cross_reference_summary(
                method, environ, start_response
            )

        if path == "/cross-reference-usage":
            # Per-repository cross-reference usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_usage(
                method, environ, start_response
            )

        if path == "/cross-reference-targets":
            # Per-resolved-local-target cross-reference usage view; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_targets(
                method, environ, start_response
            )

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/advisories":
            return _handle_advisories(method, environ, start_response)

        if path == "/graph":
            return _handle_graph(method, environ, start_response)

        if path == "/graph/stats":
            return _handle_graph_stats(method, environ, start_response)

        if path == "/dependency-closure-summary":
            # Per-resource dependency closure size summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_closure_summary(
                method, environ, start_response
            )

        if path == "/dependency-usage":
            # Per-depended-upon-resource dependents usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_usage(method, environ, start_response)

        if path == "/category-usage":
            # Global resource usage view grouped by normalized
            # category; the handler answers the 405 (Allow: GET) for
            # every other method.
            return _handle_category_usage(method, environ, start_response)

        if path == "/digest-usage":
            # Global resource usage view grouped by registration digest;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_digest_usage(method, environ, start_response)

        if path == "/name-usage":
            # Global resource usage view grouped by registration name;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_name_usage(method, environ, start_response)

        if path == "/source-usage":
            # Global resource usage view grouped by registration source;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_source_usage(method, environ, start_response)

        if path == "/graph/path/all":
            return _handle_graph_path_all(method, environ, start_response)

        if path == "/graph/path":
            return _handle_graph_path(method, environ, start_response)

        if path == "/promotion/blockers":
            return _handle_promotion_blockers(method, environ, start_response)

        if path == "/lifecycle":
            # Global lifecycle summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_lifecycle_summary(method, environ, start_response)

        if path == "/dependency-vulnerability-impact":
            # Global dependency vulnerability impact summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_global_dependency_vulnerability_impact(
                method, environ, start_response
            )

        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            f"Field 'reason' is required when the target state is "
            f"{target!r}.",
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    current = lifecycle_store.get(raw_id)
    if (current.state, target) == ("staged", "released"):
        # Promotion requires assembled content and healthy dependencies.
        if not content_store.is_complete(raw_id):
            return _error(
                start_response,
                "409 Conflict",
                "content_not_complete",
                "Content for this resource is not complete.",
            )
        for dependency_id in store.list_dependencies(raw_id):
            if lifecycle_store.get(dependency_id).state in BLOCKING_STATES:
                return _error(
                    start_response,
                    "409 Conflict",
                    "dependency_blocked",
                    "A dependency of this resource is withdrawn or "
                    "quarantined.",
                )

    try:
        record = lifecycle_store.apply(current, target, reason)
    except LifecycleError as exc:
        return _error(
            start_response, "409 Conflict", exc.code, exc.message
        )

    # ``apply`` returns the very same record for an idempotent repeat; only a
    # real transition is stored, so a repeat never adds a record.
    if record is not current:
        lifecycle_store.set(raw_id, record)
    return _lifecycle_response(start_response, "200 OK", raw_id, record)


def _handle_lifecycle(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "GET":
        return _handle_lifecycle_get(environ, raw_id, start_response)
    if method == "POST":
        return _handle_lifecycle_post(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_lifecycle_summary(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # The summary is read-only: a declared non-empty (or malformed) body is
    # a bad request without consulting any business data. An omitted header
    # and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # No filtering or pagination parameters whatsoever are accepted.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current registry: one record per
    # registered resource in resource registration order, each with the
    # same three keys in the same order as the per-resource lifecycle read
    # (id, state, reason). A resource that never left the default state is
    # reported as staged with a null reason without materializing a record;
    # a read must therefore never store anything. Nothing is reordered,
    # each resource appears exactly once, and an empty registry is a valid
    # empty array.
    records: list[dict[str, object]] = []
    for resource in store.list_all():
        record = lifecycle_store.get(resource.id)
        records.append(
            {"id": resource.id, "state": record.state, "reason": record.reason}
        )
    return _json_response(
        start_response,
        "200 OK",
        records,
        trailing_newline=True,
    )

